import 'package:bones_api/bones_api_server.dart';

class MyBTCModule extends APIModule {
  MyBTCModule(APIRoot apiRoot) : super(apiRoot, 'btc');

  @override
  void configure() {
    routes.get('time', (request) => APIResponse.ok(DateTime.now()));
  }
}

class MyAPI extends APIRoot {
  MyAPI() : super('example', '1.0');
  @override
  Set<APIModule> loadModules() => {MyBTCModule(this)};
}

void main() async {
  var api = MyAPI();
  var serverPort = await startAPIServer(api);
  print('Server started on port $serverPort');
}
